function render(){const start=addDays(settings.startDate,(week-1)*7),actual=weekAt(settings.startDate),now=new Date(),days=weekend?7:5;
$('#header-subtitle').textContent=settings.term;$('#week-title').textContent=`第 ${week} 周`;$('#week-range').textContent=`${start.getMonth()+1}月${start.getDate()}日 — ${addDays(start,6).getMonth()+1}月${addDays(start,6).getDate()}日`;$('.rail-item b').textContent=String(week).padStart(2,'0');$('#prev').disabled=week<=1;$('#next').disabled=week>=settings.totalWeeks;$('#source-chip').innerHTML=icon(prefs.source==='existing'?'folder':'sparkles')+(prefs.source==='existing'?'我的课表 · 已保存到本机':'演示课表');$('#weekends').textContent=weekend?'隐藏周末':'显示周末';
const list=sessionsFor(allCourses(),week),grid=$('#timetable'),heading=$('#date-heading');grid.style.setProperty('--days',days);heading.style.setProperty('--days',days);grid.classList.toggle('weekend',weekend);heading.classList.toggle('weekend',weekend);let head=`<div class="month-heading">${start.getMonth()+1}月</div>`;for(let day=1;day<=days;day++){const d=addDays(start,day-1);head+=`<div class="date-day ${dateKey(d)===dateKey(now)?'today':''}"><small>${WEEKDAYS[day-1]}</small><strong>${d.getDate()}</strong></div>`;}heading.innerHTML=head;
let body='';for(let period=1;period<=12;period++){body+=`<div class="time-slot" data-clock-period="${period}" style="grid-row:${period}">${String(period).padStart(2,'0')}<small>${settings.times[period-1].split('-')[0]}<br>${settings.times[period-1].split('-')[1]}</small></div>`;for(let day=1;day<=days;day++)body+=`<div class="grid-guide" data-clock-period="${period}" data-clock-day="${day}" style="grid-row:${period};grid-column:${day+1}"></div>`;}
for(const c of list.filter(c=>c.day<=days)){const peers=list.filter(p=>p.day===c.day&&p.start<=c.end&&p.end>=c.start),lane=peers.findIndex(p=>p.sessionKey===c.sessionKey);const time=`${settings.times[c.start-1].split('-')[0]}–${settings.times[c.end-1].split('-')[1]}`;body+=`<button class="course-card tone-${c.tone||'blue'} ${c.cancelled?'cancelled':c.localOverride?'locally-changed':''}" data-course="${E(c.id)}" data-period="${c.period}" data-day="${c.day}" data-date="${dateKey(addDays(start,c.day-1))}" data-span="1" style="grid-row:${c.start}/span ${c.end-c.start+1};grid-column:${c.day+1};${peers.length>1?`width:calc(${100/peers.length}% - 2px);margin-left:calc(${100*lane/peers.length}%);`:''}" aria-label="${E(c.name+' '+WEEKDAYS[c.day-1]+' 第'+c.period+'节 '+time)}"><strong>${E(c.name)}</strong><span class="location">${icon('pin')}${E(c.location||'地点待定')}</span><span class="card-time">${c.cancelled?'停课':c.localOverride?'仅本次 · ':''}${c.cancelled?'':'第'+c.period+'节'}</span></button>`;}
grid.innerHTML=body;const hiddenWeekend=list.some(c=>c.day>5)&&!weekend;$('#schedule-hint').textContent=hiddenWeekend?'本周有周末课程，点击上方「显示周末」':'轻触课程查看详情 · 左右滑动切换周次';renderToday(actual,now);renderCourseList();syncCompanion();studio?.refresh();if(view==='user')userPage.render();appearanceLab?.refresh();}
function renderToday(actual,now){const clock=scheduleClock(allCourses(),settings,now),list=clock.today;$('#today-label').textContent=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(now);$('#today-list').innerHTML=list.length?list.map(c=>`<button class="agenda-card tone-${c.tone||'blue'} ${c.cancelled?'cancelled':c.localOverride?'locally-changed':''}" data-course="${E(c.id)}" data-period="${c.period}" data-day="${c.day}" data-date="${c.date}"><div class="agenda-time">${settings.times[c.period-1].split('-')[0]}<small>${settings.times[c.period-1].split('-')[1]}</small></div><div class="agenda-title"><h3>${c.cancelled?'停课 · ':''}第${c.period}节 · ${E(c.name)}</h3><p>${E(c.location||'地点待定')} · ${E(c.teacher||'个人安排')}</p></div>${icon('chevron-right')}</button>`).join(''):`<div class="empty-message">${icon('sun')}<p>今天没有课程<br>留一点时间，给喜欢的事。</p></div>`;refreshLiveClock(now,clock);}
function refreshLiveClock(now=new Date(),clock=scheduleClock(allCourses(),settings,now)){
 const current=clock.current;liveCapsule?.render(clock,now);
 for(const el of $$('#timetable .course-card,#today-list .agenda-card')){const isToday=el.closest('#today-list')||week===clock.week;const active=Boolean(isToday&&current.some(c=>c.id===el.dataset.course&&c.period===Number(el.dataset.period)&&c.day===Number(el.dataset.day)));el.classList.toggle('is-current',active);if(active)el.setAttribute('aria-current','time');else el.removeAttribute('aria-current');}
 for(const el of $$('#timetable [data-clock-period]'))el.classList.toggle('is-now',week===clock.week&&clock.withinTerm&&clock.period>0&&Number(el.dataset.clockPeriod)===clock.period&&(!el.dataset.clockDay||Number(el.dataset.clockDay)===clock.day));
 studio?.refreshClock();armLiveClock(clock,now);
}
function renderCourseList(){const needle=$('#search').value.trim().toLowerCase(),groups=new Map();for(const c of rawCourses()){if(![c.name,c.teacher,c.location].join(' ').toLowerCase().includes(needle))continue;const key=c.name+'|'+c.teacher;if(!groups.has(key))groups.set(key,{course:c,count:0});groups.get(key).count++;}$('#course-list').innerHTML=groups.size?[...groups.values()].map(({course:c,count})=>`<button class="list-card" data-course="${E(c.id)}"><span class="list-icon tone-${c.tone||'blue'}">${icon(c.personal?'user':'book')}</span><div><h3>${E(c.name)}</h3><p>${E(c.teacher||'个人安排')} · ${count} 条排课记录</p></div>${icon('chevron-right')}</button>`).join(''):'<div class="empty-message">没有找到相关课程</div>';}
function setView(next){view=next;document.body.dataset.view=next;if(!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelector('.canvas-content').animate([{opacity:.4,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:230,easing:'cubic-bezier(.2,.8,.2,1)'});for(const name of ['week','today','courses','user'])$('#'+name+'-view').hidden=name!==next;$('#week-bar').hidden=next!=='week';$('#weekends').hidden=next!=='week';$('#view-title').textContent={week:'我的课表',today:'今日安排',courses:'全部课程',user:'用户'}[next];$$('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===next));$('#source-info').hidden=next==='user';$('#live-status').hidden=!['week','today'].includes(next);$('#fab').hidden=next==='user';$('#refresh-schedule').hidden=next!=='week';$('.app-canvas').scrollTop=0;render();}
function showCourse(id,period,occurrenceDate){const original=rawCourses().find(c=>c.id===id);if(!original)return;activeCourse=original;const selectedWeek=occurrenceDate?weekAt(settings.startDate,new Date(occurrenceDate+'T12:00:00')):week,single=Number.isInteger(period)&&period>=original.start&&period<=original.end,session=single?sessionsFor(allCourses(),selectedWeek,original.day).find(c=>c.id===id&&c.period===period):null,c=session||original;const rows=[['clock',`${WEEKDAYS[c.day-1]} · 第 ${single?period:c.start===c.end?c.start:c.start+'–'+c.end} 节`,`${settings.times[(single?period:c.start)-1].split('-')[0]} — ${settings.times[(single?period:c.end)-1].split('-')[1]}`],['pin',c.location||'地点待定','上课地点'],['user',c.teacher||'个人安排','任课教师'],['calendar',single?(occurrenceDate||dateKey(addDays(settings.startDate,(selectedWeek-1)*7+c.day-1))):original.weeks.join('、')+' 周',single?'这一次的日期':'上课周次']];$('#detail-content').innerHTML=`<div class="detail-icon tone-${c.tone||'blue'}">${icon(c.personal?'user':'book')}</div><div class="detail-heading"><h2>${E(c.name)}</h2><button class="plain-icon" data-close="detail-sheet" aria-label="关闭">${icon('close')}</button></div><span class="detail-chip">${c.cancelled?'这一次已停课':c.localOverride?'这一次已调整':c.personal?'个人安排':prefs.source==='existing'?'本机课表':'演示课程'}</span>${rows.map(([symbol,title,sub])=>`<div class="detail-row">${icon(symbol)}<p>${E(title)}<small>${E(sub)}</small></p></div>`).join('')}${c.note?`<p class="sheet-tip">${E(c.note)}</p>`:''}${c.personal?`<button class="action-row" id="delete-personal"><span style="color:#c77e79">删除整条个人安排（第${original.start===original.end?original.start:original.start+'–'+original.end}节）</span></button>`:''}`;overridesUI?.show({course:original,week:single?selectedWeek:null,period:single?period:null,date:occurrenceDate});openSheet('#detail-sheet');}
function showBinding(){setView('user');}
function openWeeks(){$('#week-options').innerHTML=Array.from({length:settings.totalWeeks},(_,i)=>`<button class="${week===i+1?'selected':''}" data-week="${i+1}">第 ${i+1} 周</button>`).join('');openSheet('#week-sheet');}
function changeWeek(delta){week=Math.max(1,Math.min(settings.totalWeeks,week+delta));render();}
const accents=['#368bc1','#579b8e','#8174b8','#c28b68','#546f98'];$('#accent-options').innerHTML=accents.map((color,i)=>`<button data-accent="${color}" style="--swatch:${color}" aria-label="${['天空蓝','薄荷绿','雾紫色','暖杏色','灰蓝色'][i]}主色"></button>`).join('');
document.addEventListener('click',event=>{const close=event.target.closest('[data-close]');if(close)document.getElementById(close.dataset.close).close();const navigation=event.target.closest('[data-view]');if(navigation)setView(navigation.dataset.view);const course=event.target.closest('[data-course]');if(course)showCourse(course.dataset.course,Number(course.dataset.period),course.dataset.date);const weekButton=event.target.closest('[data-week]');if(weekButton){week=Number(weekButton.dataset.week);render();$('#week-sheet').close();}const accent=event.target.closest('[data-accent]');if(accent){prefs.accent=accent.dataset.accent;applyPrefs();savePrefs();}const bg=event.target.closest('[data-wallpaper]');if(bg){prefs.wallpaper=bg.dataset.wallpaper;applyPrefs();savePrefs();}const action=event.target.closest('[data-action]')?.dataset.action;if(action==='appearance'){applyPrefs();openSheet('#appearance-sheet');}else if(action==='dark'){prefs.dark=!prefs.dark;applyPrefs();savePrefs();}else if(action==='binding')showBinding();else if(action==='menu')openSheet('#menu-sheet');else if(action==='existing')useExisting();else if(action==='sample')useSample();else if(action==='search'){setView('courses');$('#search').focus();}if(event.target.closest('#delete-personal')&&activeCourse?.personal){personal=personal.filter(c=>c.id!==activeCourse.id);try{localStorage.setItem('course-compass.demo.personal',JSON.stringify(personal));}catch{notify('保存失败，重新打开后删除可能不保留。');}$('#detail-sheet').close();render();notify('个人安排已删除');}});
$('#prev').onclick=()=>changeWeek(-1);$('#next').onclick=()=>changeWeek(1);$('#this-week').onclick=()=>{week=Math.max(1,Math.min(settings.totalWeeks,weekAt(settings.startDate)));render();};$('#week-picker').onclick=openWeeks;$('#weekends').onclick=()=>{weekend=!weekend;prefs.weekend=weekend;savePrefs();render();};$('#search').oninput=renderCourseList;
for(const key of ['blur','shade','opacity','position'])$('#'+key).oninput=event=>{prefs[key]=Number(event.target.value);applyPrefs();savePrefs();};
$('#fab').onclick=()=>{$('#add-form').reset();$('#add-form').elements.day.value=(new Date().getDay()+6)%7+1;$('#add-error').textContent='';openSheet('#add-sheet');};
$('#add-form').onsubmit=event=>{event.preventDefault();try{const fields=Object.fromEntries(new FormData(event.target));const c={...validateCourse({...fields,weeks:[week],teacher:'',color:'blue'}),personal:true,tone:'slate'};const updated=[...personal,c];localStorage.setItem('course-compass.demo.personal',JSON.stringify(updated));personal=updated;$('#add-sheet').close();if(c.day>5){weekend=true;prefs.weekend=true;savePrefs();}setView('week');notify('已添加到当前周');}catch(error){$('#add-error').textContent=error.message;}};
let touchStart;$('#timetable').addEventListener('touchstart',event=>{if(weekend)return;touchStart={x:event.touches[0].clientX,y:event.touches[0].clientY};},{passive:true});$('#timetable').addEventListener('touchend',event=>{if(!touchStart||weekend)return;const dx=event.changedTouches[0].clientX-touchStart.x,dy=event.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>80&&Math.abs(dx)>Math.abs(dy)*1.5)changeWeek(dx<0?1:-1);touchStart=null;},{passive:true});
function showCustom(blob){if(customURL)URL.revokeObjectURL(customURL);customURL=URL.createObjectURL(blob);document.documentElement.style.setProperty('--wallpaper',`url("${customURL}")`);$('#wallpaper').classList.add('custom');appearanceLab?.onWallpaperChange();}
const cropEditor=createCropEditor({notify,openSheet,load:()=>imageStore('get',null,'original'),save:async(cropped,original)=>{await imageStore('put',original,'original');await imageStore('put',cropped);showCustom(cropped);prefs.wallpaper='custom';prefs.position=50;applyPrefs();savePrefs();}});
$('#choose-wallpaper').onclick=()=>$('#wallpaper-file').click();$('#recrop-wallpaper').onclick=()=>cropEditor.open();$('#wallpaper-file').onchange=event=>{const file=event.target.files[0];event.target.value='';if(file)cropEditor.open(file);};

$('#appearance-font').onchange=e=>{prefs.font=e.target.value;applyPrefs();savePrefs();};
$('#appearance-haptics').onchange=e=>{prefs.haptics=e.target.checked;savePrefs();};
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(a&&!a.dataset.managedDownload&&window.CourseCompass?.openLink&&/^https?:/.test(a.href)){e.preventDefault();window.CourseCompass.openLink(a.href);}});
let lastHaptic=0;document.addEventListener('click',e=>{if(!prefs.haptics||!e.target.closest('button,a')||e.target.closest(':disabled')||performance.now()-lastHaptic<65)return;lastHaptic=performance.now();if(window.CourseCompass?.haptic)window.CourseCompass.haptic();});
const userPage=setupUser({getSettings:()=>settings,notify,setView});
$('#refresh-schedule').onclick=()=>{closeSheets();if(currentSchool().adapter==='manual'){openSheet('#table-sheet');return;}if(window.CourseCompass?.syncPortal){notify('正在重新查询教务课表…');window.CourseCompass.syncPortal();}else{showBinding();notify('教务刷新需要 Android 版，可先导入 PDF / JSON');}};
setupCompanion({notify,openSheet});
let lastCompanion='';
function syncCompanion(){if(!window.CourseCompass?.updateSchedule)return;try{const raw=localStorage.getItem('course-compass.v1'),saved=raw?validateEnvelope(JSON.parse(raw)):null;const snapshot={version:1,widget:readPersonal().widget,settings:saved?.settings||settingsDefault,courses:effectiveCourses([...(saved&&!saved.demo?saved.courses:[]),...personal],saved?.settings||settingsDefault,localChanges(),currentSchool().id).filter(c=>!c.cancelled)};const text=JSON.stringify(snapshot);if(text!==lastCompanion){window.CourseCompass.updateSchedule(text);lastCompanion=text;}}catch(error){console.warn('课程卡片同步失败',error.message);}}
function armLiveClock(clock,now){clearTimeout(liveTimer);if(document.hidden)return;const stamp=now.getTime(),changes=[stamp+60000-stamp%60000,...clock.current.map(c=>c.endsAt),...clock.next.map(c=>c.startsAt)].filter(t=>t>stamp);liveTimer=setTimeout(()=>{const next=new Date();if(liveDate!==dateKey(next)){liveDate=dateKey(next);render();}else refreshLiveClock(next);},Math.max(80,Math.min(...changes)-stamp+20));}
document.addEventListener('visibilitychange',()=>{clearTimeout(liveTimer);if(!document.hidden)render();});
setupDataTools({get:()=>({courses:data,settings,demo:prefs.source==='sample'}),getEffective:()=>effectiveCourses(data,settings,localChanges(),currentSchool().id).filter(c=>!c.cancelled),apply:()=>useExisting(true),notify,openSheet});
setupSchools({notify,openSheet});
async function refreshAppearance(){prefs=validateAppearance(JSON.parse(localStorage.getItem('course-compass.demo.prefs')||'{}'));applyPrefs();if(prefs.wallpaper==='custom'){const photo=await imageStore('get');if(photo)showCustom(photo);}studio?.reload();render();}
setupPackages({notify,openSheet,refreshAppearance});setupPoster({get:()=>({courses:allCourses().filter(c=>!c.cancelled),settings,week,weekend}),notify,openSheet});setupUpdates({notify,openSheet});
studio=setupStudio({get:()=>({courses:allCourses(),settings}),notify,openSheet,closeSheets,sync:syncCompanion});
appearanceLab=setupAppearanceLab({getPrefs:()=>prefs,updatePrefs:updateAppearance,getCourses:rawCourses,openSheet,notify,onPersonalChange:()=>studio?.reload()});
liveCapsule=setupLiveCapsule({getPrefs:()=>prefs,updatePrefs:updateAppearance,onOpenSession:c=>showCourse(c.id,c.period,c.date)});
overridesUI=setupOverrides({getContext:()=>({settings,schoolId:currentSchool().id}),notify,onChange:context=>{render();showCourse(context.course.id,context.period,context.date||dateKey(addDays(settings.startDate,(context.week-1)*7+context.course.day-1)));}});
if(localStorage.getItem('course-compass.v1')&&prefs.source==='sample')prefs.source='existing';
if('serviceWorker' in navigator&&!window.CourseCompass)navigator.serviceWorker.register('/sw.js').catch(()=>{});
applyPrefs();if(prefs.source==='existing'&&!useExisting(true)){prefs.source='sample';savePrefs();}render();if(prefs.wallpaper==='custom'){imageStore('get').then(blob=>{if(blob)showCustom(blob);else notify('本机壁纸暂未读取到，外观设置已保留，可尝试重新裁剪原图。');}).catch(()=>{notify('壁纸读取失败，已保留原有设置，请重启应用重试。');});}

if(startupRecoveryError)notify('本机备份或恢复未完成：'+startupRecoveryError+'。请到完整备份查看。');
